  #region Enums
  /// <summary>
  /// 任务状态枚举，统一 Quest 和 SpecialOrder 的表示。
  ///
  /// 设计约束：
  /// 1. CANCELLED 不进入 enum。普通 Quest 被取消后直接从 questLog 移除，不存在快照；
  ///    SpecialOrder 不可被玩家取消（CanBeCancelled() 硬编码 false）。
  ///    因此 "已取消的任务" 不会出现在快照中，enum 无需此值。
  /// 2. AWAITING_REWARD 必须保留。completed=true 但奖励未领取是合法快照状态：
  ///    普通 Quest: completed.Value=true &amp;&amp; moneyReward.Value > 0
  ///    SpecialOrder: questState=Complete &amp;&amp; unclaimedRewards.ContainsKey(farmerId)
  ///
  /// 映射关系：
  ///   IN_PROGRESS:
  ///     普通Quest: completed=false
  ///     SpecialOrder: questState == SpecialOrderStatus.InProgress
  ///
  ///   AWAITING_REWARD:
  ///     普通Quest: completed=true &amp;&amp; moneyReward.Value > 0（奖励待领取）
  ///     SpecialOrder: questState == Complete &amp;&amp; unclaimedRewards.ContainsKey(currentFarmerId)
  ///
  ///   COMPLETED:
  ///     普通Quest: completed=true &amp;&amp; moneyReward.Value &lt;= 0（奖励已领取或无奖励）
  ///     SpecialOrder: questState == Complete &amp;&amp; !unclaimedRewards.ContainsKey(currentFarmerId)
  ///
  ///   FAILED:
  ///     普通Quest: 不使用（普通 Quest 无 Failed 状态）
  ///     SpecialOrder: questState == SpecialOrderStatus.Failed（超时未完成）
  /// </summary>
  public enum QuestStatus {
    [pbr::OriginalName("QUEST_STATUS_UNSPECIFIED")] Unspecified = 0,
    [pbr::OriginalName("QUEST_IN_PROGRESS")] QuestInProgress = 1,
    /// <summary>
    /// 目标达成，奖励待领取
    /// </summary>
    [pbr::OriginalName("QUEST_AWAITING_REWARD")] QuestAwaitingReward = 2,
    /// <summary>
    /// 完成且奖励已领取（或无奖励）
    /// </summary>
    [pbr::OriginalName("QUEST_COMPLETED")] QuestCompleted = 3,
    /// <summary>
    /// 仅 SpecialOrder 使用
    /// </summary>
    [pbr::OriginalName("QUEST_FAILED")] QuestFailed = 4,
  }

  /// <summary>
  /// 机器当前工作状态（来自客观字段派生，不是行动建议）。
  /// </summary>
  public enum MachineState {
    [pbr::OriginalName("MACHINE_STATE_UNSPECIFIED")] Unspecified = 0,
    /// <summary>
    /// 空闲：无 heldObject 且 readyForHarvest=false
    /// </summary>
    [pbr::OriginalName("MACHINE_IDLE")] MachineIdle = 1,
    /// <summary>
    /// 加工中：heldObject 非空且 minutes_until_ready > 0
    /// </summary>
    [pbr::OriginalName("MACHINE_PROCESSING")] MachineProcessing = 2,
    /// <summary>
    /// 完成：readyForHarvest=true，产物可取出
    /// </summary>
    [pbr::OriginalName("MACHINE_READY")] MachineReady = 3,
  }

